solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <map>
#include <string>
#include <utility>
#include <vector>

class SpecialPool
{
public:
    explicit SpecialPool(std::size_t pageSize) : m_pageSize{ pageSize } {}

    int allocate(std::size_t bytes, std::uint32_t tag)
    {
        if (bytes == 0 || bytes > m_pageSize) return 0;
        const int h{ m_next++ };
        Block b{ bytes, tag, false, std::vector<std::uint8_t>(m_pageSize, 0) };
        std::fill(b.page.begin(), b.page.end() - static_cast<std::ptrdiff_t>(bytes), std::uint8_t{ 0xAA });
        m_blocks.emplace(h, std::move(b));
        return h;
    }

    std::string write(int handle, std::size_t offset, std::size_t length) { return access(handle, offset, length, true); }
    std::string read(int handle, std::size_t offset, std::size_t length) const { return access(handle, offset, length, false); }

    void underrun(int handle, std::size_t bytesBefore)
    {
        auto it{ m_blocks.find(handle) };
        if (it == m_blocks.end() || it->second.freed) return;
        Block& b{ it->second };
        const std::size_t fill{ m_pageSize - b.size };
        const std::size_t n{ std::min(bytesBefore, fill) };
        for (std::size_t i{ 0 }; i < n; ++i) b.page[fill - 1 - i] = 0x00;
    }

    std::string free(int handle, std::uint32_t tag)
    {
        auto it{ m_blocks.find(handle) };
        if (it == m_blocks.end()) return "unknown handle";
        Block& b{ it->second };
        if (b.freed) return "double free";
        if (b.tag != tag) return "tag mismatch";
        const std::size_t fill{ m_pageSize - b.size };
        const bool intact{ std::all_of(b.page.begin(), b.page.begin() + static_cast<std::ptrdiff_t>(fill), [](std::uint8_t v) { return v == 0xAA; }) };
        b.freed = true;
        b.page.clear();
        b.page.shrink_to_fit();
        return intact ? "ok" : "underrun detected";
    }

    int pagesInUse() const
    {
        return static_cast<int>(std::count_if(m_blocks.begin(), m_blocks.end(), [](const auto& e) { return !e.second.freed; }));
    }

    std::vector<std::string> unloadReport() const
    {
        std::map<std::string, std::pair<int, std::size_t>> byTag;
        for (const auto& [h, b] : m_blocks)
            if (!b.freed) { auto& e{ byTag[tagText(b.tag)] }; ++e.first; e.second += b.size; }
        std::vector<std::string> out;
        for (const auto& [tag, e] : byTag)
            out.push_back(tag + ": " + std::to_string(e.first) + (e.first == 1 ? " allocation, " : " allocations, ") + std::to_string(e.second) + " bytes");
        return out;
    }

private:
    struct Block { std::size_t size; std::uint32_t tag; bool freed; std::vector<std::uint8_t> page; };

    static std::string tagText(std::uint32_t tag)
    {
        std::string s;
        for (int i{ 0 }; i < 4; ++i) { const char c{ static_cast<char>((tag >> (8 * i)) & 0xFF) }; s += (c >= 32 && c < 127) ? c : '.'; }
        return s;
    }

    std::string access(int handle, std::size_t offset, std::size_t length, bool isWrite) const
    {
        const auto it{ m_blocks.find(handle) };
        if (it == m_blocks.end()) return "unknown handle";
        const Block& b{ it->second };
        if (b.freed) return isWrite ? "write to freed memory" : "read of freed memory";
        const std::size_t end{ offset + length };
        if (end > b.size) return (isWrite ? "overrun by " : "read past the end by ") + std::to_string(end - b.size) + " bytes";
        return "";
    }

    std::size_t m_pageSize;
    std::map<int, Block> m_blocks;
    int m_next{ 1 };
};

unitTests:
using Lines = std::vector<std::string>;
const std::uint32_t CIRN = 0x6E726943u, CIRB = 0x42726943u;
TEST("allocations") {
    SpecialPool p{ 4096 }; CHECK_EQ(p.allocate(100, CIRN), 1); CHECK_EQ(p.allocate(0, CIRN), 0); CHECK_EQ(p.allocate(5000, CIRN), 0); CHECK_EQ(p.allocate(4096, CIRB), 2);
    CHECK_EQ(p.pagesInUse(), 2);
}
TEST("overruns fault at once") {
    SpecialPool p{ 4096 }; const int h = p.allocate(100, CIRN);
    CHECK_EQ(p.write(h, 0, 100), std::string("")); CHECK_EQ(p.write(h, 90, 20), std::string("overrun by 10 bytes")); CHECK_EQ(p.write(h, 100, 1), std::string("overrun by 1 bytes"));
    CHECK_EQ(p.read(h, 99, 1), std::string("")); CHECK_EQ(p.read(h, 96, 8), std::string("read past the end by 4 bytes")); CHECK_EQ(p.write(42, 0, 1), std::string("unknown handle"));
}
TEST("use after free and double free") {
    SpecialPool p{ 4096 }; const int h = p.allocate(64, CIRN);
    CHECK_EQ(p.free(h, CIRB), std::string("tag mismatch")); CHECK_EQ(p.pagesInUse(), 1);
    CHECK_EQ(p.free(h, CIRN), std::string("ok")); CHECK_EQ(p.write(h, 0, 1), std::string("write to freed memory")); CHECK_EQ(p.read(h, 0, 1), std::string("read of freed memory"));
    CHECK_EQ(p.free(h, CIRN), std::string("double free")); CHECK_EQ(p.free(77, CIRN), std::string("unknown handle")); CHECK_EQ(p.pagesInUse(), 0);
}
TEST("underruns are found at free") {
    SpecialPool p{ 4096 }; const int a = p.allocate(64, CIRN), b = p.allocate(64, CIRN), c = p.allocate(4096, CIRN);
    p.underrun(a, 4); CHECK_EQ(p.free(a, CIRN), std::string("underrun detected")); CHECK_EQ(p.free(b, CIRN), std::string("ok"));
    p.underrun(c, 8); CHECK_EQ(p.free(c, CIRN), std::string("ok"));
}
TEST("leaks at unload") {
    SpecialPool p{ 256 }; p.allocate(64, CIRN); p.allocate(32, CIRN); const int x = p.allocate(200, CIRB); p.allocate(10, CIRB);
    p.free(x, CIRB); CHECK_EQ(p.unloadReport(), (Lines{ "CirB: 1 allocation, 10 bytes", "Cirn: 2 allocations, 96 bytes" }));
    SpecialPool clean{ 256 }; const int y = clean.allocate(8, CIRN); clean.free(y, CIRN); CHECK(clean.unloadReport().empty());
}

